package ai.taskforge.api;
import ai.taskforge.domain.*; import ai.taskforge.repo.*; import ai.taskforge.service.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/approvals") public class ApprovalController { private final ApprovalRepository approvals;private final TaskRepository tasks;private final UserRepository users;private final CurrentUser current;private final NotificationService notifications;private final AuditService audit;public ApprovalController(ApprovalRepository a,TaskRepository t,UserRepository u,CurrentUser c,NotificationService n,AuditService log){approvals=a;tasks=t;users=u;current=c;notifications=n;audit=log;} record RequestInput(UUID approverId,@Size(max=1000) String comment){} record DecisionInput(@Size(max=1000) String comment){} record View(UUID id,UUID taskId,String taskTitle,String requestedBy,String approver,ApprovalStatus status,String comment,java.time.Instant requestedAt){} @GetMapping List<View> mine(){return approvals.findByApproverIdAndStatus(current.get().getId(),ApprovalStatus.PENDING).stream().map(this::view).toList();} @PostMapping("/tasks/{taskId}") View request(@PathVariable UUID taskId,@Valid @RequestBody RequestInput in){var task=tasks.findById(taskId).orElseThrow(()->new ApiException("NOT_FOUND","Task not found."));var approver=in.approverId()==null?users.findByRole(Role.MANAGER).stream().findFirst().orElseThrow(()->new ApiException("NO_APPROVER","No manager is available.")):users.findById(in.approverId()).orElseThrow(()->new ApiException("NOT_FOUND","Approver not found."));var approval=approvals.save(new Approval(task,current.get(),approver,in.comment()));notifications.send(approver,"APPROVAL_REQUESTED","Approval requested for: "+task.getTitle());audit.record(current.get(),"APPROVAL_REQUESTED","TASK",task.getId(),null,"Approver: "+approver.getDisplayName());return view(approval);} @PostMapping("/{id}/approve") @PreAuthorize("hasAnyRole('ADMIN','MANAGER')") View approve(@PathVariable UUID id,@Valid @RequestBody DecisionInput in){return decide(id,ApprovalStatus.APPROVED,in.comment());} @PostMapping("/{id}/reject") @PreAuthorize("hasAnyRole('ADMIN','MANAGER')") View reject(@PathVariable UUID id,@Valid @RequestBody DecisionInput in){return decide(id,ApprovalStatus.REJECTED,in.comment());} private View decide(UUID id,ApprovalStatus status,String comment){var a=approvals.findById(id).orElseThrow(()->new ApiException("NOT_FOUND","Approval not found."));if(!current.elevated()||!a.getApprover().getId().equals(current.get().getId())&&current.get().getRole()!=Role.ADMIN)throw new ApiException("FORBIDDEN","Only the assigned approver can decide this request.");a.decide(status,comment);a=approvals.save(a);notifications.send(a.getRequestedBy(),"APPROVAL_"+status,"Your request for "+a.getTask().getTitle()+" was "+status.name().toLowerCase()+".");audit.record(current.get(),"APPROVAL_"+status,"TASK",a.getTask().getId(),"PENDING",status.name());return view(a);} private View view(Approval a){return new View(a.getId(),a.getTask().getId(),a.getTask().getTitle(),a.getRequestedBy().getDisplayName(),a.getApprover().getDisplayName(),a.getStatus(),a.getComment(),a.getRequestedAt());} }
